"""XML and SVG minification helpers used by the CLI."""
import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from cssmin import minify_css

_TOKEN = re.compile(r'<!--.*?-->|<!\[CDATA\[.*?\]\]>|<\?.*?\?>|<![^>]*>|</?[^>]+>|[^<]+|<', re.S)
_TAG = re.compile(r'^<\s*([A-Za-z_:][\w:.-]*)([\s\S]*?)\s*/?>$')
_ENTITY = re.compile(r'&(#(?:x[0-9a-fA-F]+|[0-9]+)|[A-Za-z][\w.-]*);')
_ATTR = re.compile(r'([\s]+[^\s=/>]+)\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+))')


def _collapse_text(text, keep=False):
    if not text:
        return ''
    # Whitespace-only layout between markup tags carries no XML text value.
    if not text.strip():
        return re.sub(r'[\t\r\n ]+', ' ', text) if keep and '\n' not in text and '\r' not in text else ''
    return re.sub(r'[\t\r\n ]+', lambda m: '\n' if '\n' in m.group() or '\r' in m.group() else ' ', text)


def _xml_entities(text):
    unknown = []
    def decode(m):
        name = m[1]
        try:
            if name.startswith('#x'):
                char = chr(int(name[2:], 16))
            elif name.startswith('#'):
                char = chr(int(name[1:]))
            else:
                char = {'amp':'&','lt':'<','gt':'>','quot':'"','apos':"'"}.get(name)
                if char is None:
                    unknown.append(m[0])
                    return '\ue000'
            if name.startswith('#') and ord(char) > 127:
                unknown.append(m[0])
                return '\ue000'
            if not name.startswith('#') and not char.isprintable() and char not in '\t\n\r':
                return m[0]
            return char
        except (ValueError, OverflowError):
            unknown.append(m[0])
            return '\ue000'
    text = _ENTITY.sub(decode, text)
    text = text.replace('&', '&amp;').replace('<', '&lt;')
    for entity in unknown:
        text = text.replace('\ue000', entity, 1)
    return text


def _attr_entities(value):
    protected = []
    def hold(text):
        token = '\ue000' + str(len(protected)) + '\ue001'
