    s = re.sub(r'(?i)(-?(?:\d+(?:\.\d*)?|\.\d+))px\b', r'\1', s)
    color_map = {'#ff0000':'red','#0000ff':'#00f','#008000':'#080','#000000':'#000',
                 '#ffffff':'#fff','#ffff00':'#ff0','#00ffff':'#0ff','#ff00ff':'#f0f'}
    for h, replacement in color_map.items():
