    path_num = r'[-+]?(?:\d*\.\d+|\d+\.?\d*)(?:e[-+]?\d+)?'
    path_pair = path_num + r'[\s,]+' + path_num
    path_run = re.compile(r'(?i)([Mm]\s*' + path_pair + r'(?:\s*[Ll]\s*' + path_pair + r')+)')
    def shorten_path(m):
        value = re.sub(r'\s*[Ll]\s*', ' ', m[1], flags=re.I)
        value = re.sub(r'([Mm])\s+', r'\1', value)
        return re.sub(r'[,\s]+', ' ', value).strip()
