               lambda m: m[1]+m[2]+path_run.sub(shorten_path, m[3])+m[2], s)
    s = re.sub(r'(?i)(\bd\s*=\s*)(["\'])(.*?)\2',
               lambda m: m[1]+m[2]+re.sub(r'\s+[Zz]\b', 'z', m[3])+m[2], s)
    for i, replacement in enumerate(css_parts):
        s = s.replace('__SVG_STYLE_'+str(i)+'__', replacement)
    return minify_xml(s, {'xml_keep_whitespace': False, '_keep_comments': keep_comments})

